#include <string>

class Solution {
public:
    std::string mergeClose(std::string s) {
        std::string res = "";
        for (char c : s) {
            if (!res.empty() && res.back() == c) res.pop_back();
            else res.push_back(c);
        }
        return res;
    }
};

class Solution {
    public String mergeClose(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (sb.length() > 0 && sb.charAt(sb.length() - 1) == c) {
                sb.deleteCharAt(sb.length() - 1);
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

function mergeClose(s) {
    const res = [];
    for (const c of s) {
        if (res.length > 0 && res[res.length - 1] === c) {
            res.pop();
        } else {
            res.push(c);
        }
    }
    return res.join('');
}
